<?php
require_once __DIR__ . '/includes/functions.php';$u=require_role('lender');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$businessId=(int)($_POST['business_id']??0);$decision=$_POST['decision']??'';$reason=trim($_POST['reason']??'');if(!in_array($decision,['under_review','approved','declined','more_information'],true)||$reason==='')$error=t('Choose a decision and provide a reason.','Choisissez une décision et indiquez un motif.');else{$s=$pdo->prepare('SELECT id FROM consents WHERE business_user_id=? AND lender_user_id=? AND revoked_at IS NULL');$s->execute([$businessId,$u['id']]);if(!$s->fetch()){$error=t('This business has not consented to share with you.','Cette entreprise n’a pas autorisé le partage avec vous.');}else{$s=$pdo->prepare('INSERT INTO lender_decisions (business_user_id,lender_user_id,decision,reason) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE decision=VALUES(decision),reason=VALUES(reason),decided_at=NOW()');$s->execute([$businessId,$u['id'],$decision,$reason]);flash('success',t('Decision recorded with a reason.','Décision enregistrée avec un motif.'));redirect('lender_matches.php');}}}
$sql="SELECT DISTINCT u.id,u.full_name,u.business_name,u.sector,u.years_operating,u.monthly_revenue,u.monthly_expenses,u.requested_amount,u.registration_status,u.has_bank_account,u.collateral_available,u.business_description,c.id AS consent_id,c.consented_at,lc.institution_name,lc.min_amount,lc.max_amount,lc.sector AS criteria_sector,lc.min_years_operating,lc.requires_registration,lc.requires_bank_account,ld.decision,ld.reason FROM consents c JOIN users u ON u.id=c.business_user_id LEFT JOIN lender_criteria lc ON lc.id=c.criteria_id LEFT JOIN lender_decisions ld ON ld.business_user_id=u.id AND ld.lender_user_id=c.lender_user_id WHERE c.lender_user_id=? AND c.revoked_at IS NULL ORDER BY c.consented_at DESC";
$s=$pdo->prepare($sql);$s->execute([$u['id']]);$rows=$s->fetchAll();$pageTitle=t('Consented business matches','Entreprises ayant consenti');require __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow"><?= e(t('CONSENTED BUSINESS FILES','DOSSIERS AUTORISÉS')) ?></span><h1><?= e(t('Matched businesses','Entreprises correspondantes')) ?></h1><p><?= e(t('Only business owners who have consented to share with your account appear here. Access ends when consent is revoked.','Seules les entreprises ayant autorisé le partage avec votre compte apparaissent ici. L’accès prend fin en cas de révocation.')) ?></p></div><a class="btn btn-outline" href="<?= e(url('lender_criteria.php')) ?>"><?= e(t('Manage criteria','Gérer les critères')) ?></a></div>
<?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><div class="notice-box"><span class="notice-icon">i</span><p><?= e(t('Treat readiness indicators as supporting information, not an automated credit decision. Assess applications using your institution’s lawful process and explain outcomes.','Considérez les indicateurs comme des informations complémentaires, et non comme une décision automatisée. Évaluez les demandes selon les procédures légales de votre institution et expliquez les résultats.')) ?></p></div>
<?php if(!$rows): ?><section class="panel empty-state"><h2><?= e(t('No consented business files yet','Aucun dossier autorisé pour le moment')) ?></h2><p><?= e(t('Publish clear criteria and business owners can decide whether to share their profiles.','Publiez des critères clairs ; les entrepreneurs pourront décider de partager leur profil.')) ?></p><a class="btn btn-primary" href="<?= e(url('lender_criteria.php')) ?>"><?= e(t('Set criteria','Définir les critères')) ?></a></section><?php else: ?><div class="business-review-grid"><?php foreach($rows as $r): ?><article class="panel review-card"><div class="review-card-head"><div class="institution-mark"><?= e(strtoupper(substr($r['business_name']?:$r['full_name'],0,1))) ?></div><div><h2><?= e($r['business_name']?:$r['full_name']) ?></h2><p><?= e(ucfirst($r['sector']??'—')) ?> · <?= (int)$r['years_operating'] ?> <?= e(t('years operating','années d’activité')) ?></p></div></div><div class="review-finances"><div><small><?= e(t('Monthly revenue','Revenu mensuel')) ?></small><strong><?= e(number_format((float)$r['monthly_revenue'],0)) ?> XAF</strong></div><div><small><?= e(t('Monthly expenses','Dépenses mensuelles')) ?></small><strong><?= e(number_format((float)$r['monthly_expenses'],0)) ?> XAF</strong></div><div><small><?= e(t('Loan requested','Prêt demandé')) ?></small><strong><?= e(number_format((float)$r['requested_amount'],0)) ?> XAF</strong></div></div><dl class="detail-list"><div><dt><?= e(t('Registration','Immatriculation')) ?></dt><dd><?= e($r['registration_status']??'—') ?></dd></div><div><dt><?= e(t('Business bank account','Compte bancaire professionnel')) ?></dt><dd><?= e((int)$r['has_bank_account']===1?t('Yes','Oui'):t('No / not stated','Non / non renseigné')) ?></dd></div><div><dt><?= e(t('Collateral','Garanties')) ?></dt><dd><?= e((int)$r['collateral_available']===1?t('Available','Disponible'):t('Not available / not stated','Indisponible / non renseigné')) ?></dd></div></dl><?php if($r['business_description']): ?><p><?= e($r['business_description']) ?></p><?php endif; ?><small class="muted"><?= e(t('Consent granted','Consentement accordé')) ?>: <?= e($r['consented_at']) ?></small><form method="post" class="decision-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="business_id" value="<?= (int)$r['id'] ?>"><label><?= e(t('Decision','Décision')) ?><select name="decision" required><option value="under_review" <?= ($r['decision']??'')==='under_review'?'selected':'' ?>><?= e(t('Under review','En cours d’examen')) ?></option><option value="more_information" <?= ($r['decision']??'')==='more_information'?'selected':'' ?>><?= e(t('More information needed','Informations complémentaires requises')) ?></option><option value="approved" <?= ($r['decision']??'')==='approved'?'selected':'' ?>><?= e(t('Approved by lender','Approuvé par le prêteur')) ?></option><option value="declined" <?= ($r['decision']??'')==='declined'?'selected':'' ?>><?= e(t('Declined by lender','Refusé par le prêteur')) ?></option></select></label><label><?= e(t('Reason / next step (required)','Motif / prochaine étape (obligatoire)')) ?><textarea name="reason" rows="3" required><?= e($r['reason']??'') ?></textarea></label><button class="btn btn-primary full-width" type="submit"><?= e(t('Save decision','Enregistrer la décision')) ?></button></form></article><?php endforeach; ?></div><?php endif; ?>
